function Sj() {
	return yj.struct.combinator.merge([
		yj.struct.generator.atomGroups({ "residue-test": yj.core.set.has([yj.set(...bj.nucleic), yj.ammp("label_comp_id")]) }),
		yj.struct.filter.pick({
			0: yj.struct.generator.atomGroups({ "group-by": yj.ammp("residueKey") }),
			test: yj.core.logic.and([yj.core.rel.eq([yj.struct.atomSet.atomCount(), 1]), yj.core.rel.eq([yj.ammp("label_atom_id"), yj.atomName("P")])])
		}),
		yj.struct.filter.pick({
			0: yj.struct.generator.atomGroups({ "group-by": yj.ammp("residueKey") }),
			test: yj.core.logic.or([yj.core.set.isSubset([sj([
				"C1'",
				"C2'",
				"O3'",
				"C3'",
				"C4'",
				"C5'",
				"O5'"
			]), yj.ammpSet("label_atom_id")]), yj.core.set.isSubset([sj([
				"C1*",
				"C2*",
				"O3*",
				"C3*",
				"C4*",
				"C5*",
				"O5*"
			]), yj.ammpSet("label_atom_id")])])
		})
	]);
}
function Rwe() {
	return yj.struct.generator.atomGroups({ "residue-test": yj.core.set.has([yj.set(...bj.amino), yj.ammp("label_comp_id")]) });
}
function zwe() {
	return yj.struct.combinator.merge([yj.struct.modifier.intersectBy({
		0: yj.struct.generator.atomGroups({ "residue-test": yj.core.set.has([yj.core.type.set(bj.amino), yj.ammp("label_comp_id")]) }),
		by: yj.struct.generator.atomGroups({ "atom-test": yj.core.set.has([yj.core.type.set(xj.protein), yj.ammp("label_atom_id")]) })
	}), yj.struct.modifier.intersectBy({
		0: yj.struct.generator.atomGroups({ "residue-test": yj.core.set.has([yj.core.type.set(bj.nucleic), yj.ammp("label_comp_id")]) }),
		by: yj.struct.generator.atomGroups({ "atom-test": yj.core.set.has([yj.core.type.set(xj.nucleic), yj.ammp("label_atom_id")]) })
	})]);
}
